@import url('https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,400;0,500;0,600;0,700;1,400;1,500;1,600&family=EB+Garamond:ital,wght@0,400;0,500;0,600;0,700;1,400;1,500&display=swap');

:root {

--text-color: #1a1a1a;

--bg-color: #faf8f4;

--accent-gold: #8B7432;

--accent-dark: #3d3225;

--verse-bg: #f0ece3;

--verse-border: #c5b898;

--section-border: #d4c9a8;

--subtle-text: #5a5040;

* { margin: 0; padding: 0; box-sizing: border-box; }

body {

font-family: 'EB Garamond', 'Cormorant Garamond', Georgia, serif;

font-size: 18px; line-height: 1.85; color: var(--text-color);

background-color: var(--bg-color); text-align: justify;

.container { max-width: 780px; margin: 0 auto; padding: 40px 30px 80px; }

.book-title { text-align: center; margin-bottom: 50px; padding-bottom: 30px; border-bottom: 2px solid var(--section-border); }

.book-title h1 { font-family: 'Cormorant Garamond', Georgia, serif; font-size: 2.2em; font-weight: 700; color: var(--accent-dark); letter-spacing: 0.03em; margin-bottom: 4px; }

.book-title .subtitle { font-size: 1.1em; color: var(--subtle-text); font-style: italic; }

.section-header { text-align: center; margin: 50px 0 30px; padding: 15px 0; border-top: 1px solid var(--section-border); border-bottom: 1px solid var(--section-border); }

.section-header h2 { font-family: 'Cormorant Garamond', Georgia, serif; font-size: 1.65em; font-weight: 600; color: var(--accent-dark); }

.halacha-header { text-align: center; margin: 55px 0 20px; padding: 20px 0; border-top: 2px solid var(--accent-gold); border-bottom: 2px solid var(--accent-gold); }

.halacha-header h2 { font-family: 'Cormorant Garamond', Georgia, serif; font-size: 1.65em; font-weight: 600; color: var(--accent-dark); }

.sa-excerpt { text-align: center; margin: 20px 0 35px; padding: 15px 25px; background: var(--verse-bg); border-left: 3px solid var(--accent-gold); border-right: 3px solid var(--accent-gold); font-size: 1.05em; font-style: italic; color: var(--accent-dark); line-height: 1.9; }

.ois { font-family: 'Cormorant Garamond', Georgia, serif; font-weight: 700; font-size: 1.15em; color: var(--accent-gold); margin-top: 35px; margin-bottom: 10px; display: block; }

p { margin-bottom: 18px; text-indent: 1.5em; }

p:first-of-type, .ois + p, .sa-excerpt + p, .section-header + p, .halacha-header + p { text-indent: 0; }

.verse { font-style: italic; color: var(--accent-dark); }

.source { font-size: 0.88em; color: var(--subtle-text); font-style: normal; }

.heb { font-style: italic; }

.bracket { color: var(--subtle-text); font-size: 0.95em; }

.insert { color: var(--subtle-text); font-size: 0.93em; }

.key { font-weight: 600; }

.aramaic { font-style: italic; }

.hagahah { font-variant: small-caps; font-weight: 600; color: var(--accent-gold); }

.closing { text-align: center; font-style: italic; margin: 25px 0; color: var(--accent-dark); }

.intro-block p{text-indent:0;margin-bottom:8px;font-size:17px}

.summation{background:linear-gradient(135deg,#f5f0e8 0%,#ebe5d8 100%);border:2px solid var(--border);border-radius:8px;padding:25px 30px;margin:45px 0 20px}

.summation-header{text-align:center;font-size:14px;letter-spacing:3px;text-transform:uppercase;color:var(--accent);margin-bottom:15px;font-weight:700}

.summation p{font-size:16px;text-indent:0;margin-bottom:10px;color:var(--text-light)}

.intro-block p{text-indent:0;margin-bottom:8px;font-size:17px}

